class Solution:
    def findLonely(self, nums: List[int]) -> List[int]:
        s = sorted(nums)
        n = len(s)
        res = []
        for i in range(n):
            left_ok = i == 0 or s[i - 1] < s[i] - 1
            right_ok = i == n - 1 or s[i + 1] > s[i] + 1
            if left_ok and right_ok:
                res.append(s[i])
        return res

