class Solution {
public:
    vector<int> findLonely(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        int n = nums.size();
        vector<int> res;
        for (int i = 0; i < n; i++) {
            bool l = i == 0 || nums[i - 1] < nums[i] - 1;
            bool r = i == n - 1 || nums[i + 1] > nums[i] + 1;
            if (l && r) res.push_back(nums[i]);
        }
        return res;
    }
};

